p = float(input())
p = int(p*100)
g = float(input())
g = int(g*100)

n = int(input())
coins = []
for i in range(n):
    value = float(input())
    if value >= 1.0:
        coins.append(int(value))
    else:
        coins.append(value)

dispo = []
for t in coins:
    dispo.append(int(t*100))

ar = (g - p)
if ar == 0:
    print("No coin to give back.")
elif ar > 0:
    print(f"{ar / 100:.2f}")  # --> Here comes the magic

    mr = 0
    i = 0
    n = 0
    while ar > 0:
        n = ar // dispo[i]
        if n > 0:
            if n == 1:
                print(int(n) , "coin of" , str(coins[i])+"$")
            else :
                print(int(n) , "coins of" ,str(coins[i])+"$")

        ar -= n*dispo[i]
        if i + 1 < len(coins):
            i += 1
